'use strict';
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.ReikaInteraction=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
const MOODS=['neutral','happy','thinking','magic','serious'];
function classify(text){const q=String(text??'').trim().toLowerCase().slice(0,500);if(!q)return 'neutral';if(/груст|плох|страш|боле|тревог|помоги/.test(q))return 'serious';if(/магия|волшеб|заклинан|хвост/.test(q))return 'magic';if(/почему|как |что |зачем|дума|вопрос|\?/.test(q))return 'thinking';if(/привет|спасибо|ура|счаст|рад|люблю|отлично/.test(q))return 'happy';return 'neutral';}
function speakingOpen(ms,active,enabled=true){if(!active||!enabled||!Number.isFinite(ms))return false;return Math.floor(Math.max(0,ms)/155)%3!==2;}
function validateMood(mood){return MOODS.includes(mood)?mood:'neutral';}
function createController(){let mood='neutral',auto=true,until=0;return {onReply(text,now){if(auto){mood=classify(text);until=now+5500;}},getMood(fallback,now){return auto&&now<until?mood:validateMood(fallback);},setAuto(v){auto=Boolean(v);},clear(){until=0;mood='neutral';},get auto(){return auto;},get mood(){return mood;}};}
function mount(){const panel=document.querySelector('.panel');if(!panel)return;const controller=createController();const block=document.createElement('section');block.className='reika-interaction';block.innerHTML='<h3>Поведение Рэйки · v57–v70</h3><label><input id="interactionAutoMood" type="checkbox" checked> Реагировать эмоцией на сообщения</label><label><input id="interactionAutoSpeak" type="checkbox"> Озвучивать ответы автоматически</label><label><input id="interactionMouthMotion" type="checkbox" checked> Движение рта во время речи</label><button type="button" id="interactionClear">Сбросить реакцию</button><p id="interactionStatus" role="status" aria-live="polite">Ожидание сообщений · локальные правила, не нейросеть.</p>';panel.append(block);const moodCheck=block.querySelector('#interactionAutoMood'),autoSpeak=block.querySelector('#interactionAutoSpeak'),lip=block.querySelector('#interactionMouthMotion'),status=block.querySelector('#interactionStatus');let speechStart=null,wasActive=false;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
moodCheck.onchange=()=>{controller.setAuto(moodCheck.checked);status.textContent=moodCheck.checked?'Автоматические эмоции включены.':'Автоматические эмоции отключены.';};
block.querySelector('#interactionClear').onclick=()=>{controller.clear();status.textContent='Реакция сброшена.';};
window.addEventListener('reika:reply',event=>{const text=event.detail?.text||'';controller.onReply(text,performance.now());status.textContent='Реакция: '+controller.mood+' · правила, без AI.';if(autoSpeak.checked){const input=document.getElementById('speechText'),button=document.getElementById('speechPlay');if(input&&button&&!button.disabled){input.value=text;button.click();}}});
const sync=()=>{const active=Boolean(window.ReikaSpeechController?.active);if(active&&!wasActive)speechStart=performance.now();if(!active)speechStart=null;wasActive=active;};function mouthOpen(){sync();if(!lip.checked||reduced.matches)return Boolean(window.ReikaSpeechController?.open)&&!reduced.matches&&lip.checked;return speakingOpen(performance.now()-(speechStart??performance.now()),wasActive);}
return {currentMood(fallback){return controller.getMood(fallback,performance.now());},mouthOpen,get auto(){return controller.auto;},get mood(){return controller.mood;},reset(){controller.clear();}};
}
return {MOODS,classify,speakingOpen,validateMood,createController,mount};
});
if(typeof window!=='undefined')window.ReikaInteractionController=window.ReikaInteraction.mount();
